INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 21, 'theory', 'Квиз: subprocess и разбор вывода');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 21, 0, 'Почему subprocess.run(["lvs", vg]) безопаснее, чем subprocess.run(f"lvs {vg}", shell=True), если vg приходит от пользователя?', '["Список запускается быстрее, поэтому атаковать некогда", "Список автоматически проверяет имя по правилам LVM", "Оболочка не участвует, и содержимое vg доходит до программы одним аргументом", "Список запрещает программе читать стандартный ввод"]', 2, 'Без оболочки точка с запятой и пробелы в имени ничего не значат. Но имя, начинающееся с дефиса, программа всё равно примет за опцию, поэтому имена ещё и проверяют.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 21, 1, 'Что вы получите, если запустить несуществующую программу так: subprocess.run(["nosuchtool"])?', '["Исключение FileNotFoundError", "Результат с returncode 127", "Результат с returncode -1", "Зависание до таймаута"]', 0, 'Без оболочки Питон сам не может запустить файл и бросает исключение (подкласс OSError). Код 127 вы увидели бы только через shell=True, где его сообщает оболочка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 21, 2, 'Вы передали env={"LC_ALL": "C"}, и команда перестала находить свои библиотеки и программы. Почему?', '["LC_ALL=C запрещает загрузку библиотек", "Параметр env применим только вместе с shell=True", "Значение переменной нужно передавать байтами", "env заменяет окружение целиком, и PATH с остальными переменными пропали"]', 3, 'Нужно копировать текущее окружение и добавлять свои переменные: {**os.environ, "LC_ALL": "C"}.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 21, 3, 'Что верно про вывод lvs --reportformat json в обычном режиме json (не json_std)?', '["Размеры и проценты — числа JSON, их можно сравнивать сразу", "Значения — строки, в том числе размеры; пустое поле — пустая строка", "Скрытые тома всегда включены в вывод", "Размеры всегда выдаются в байтах без суффикса"]', 1, 'Числа в кавычках — особенность режима json; json_std выдаёт настоящие числа. Размеры в байтах нужно просить явно (--units b --nosuffix), скрытые тома — флагом -a.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 21, 4, 'В выводе df -P точка монтирования /mnt/My Disk содержит пробел. Как надёжно разобрать строку?', '["line.split() и взять последний элемент", "line.split(\" \") и склеить хвост пробелом", "line.split(None, 5): шестой элемент — остаток строки", "Заменить пробелы в выводе на подчёркивания перед разбором"]', 2, 'Первые пять полей не содержат пробелов, а точка монтирования идёт последней. Ограничение числа разрезов оставляет её нетронутой, включая повторяющиеся пробелы.');
